CREATE TABLE t1(id INTEGER PRIMARY KEY,x JSON); INSERT INTO t1(id,x) VALUES (1,'{"a":null}'),(2,'{"a":123}'),(3,'{"a":4.5}'),(4,'{"a":"six"}'),(5,'{"a":[7,8]}'),(6,'{"a":{"b":9}}'),(7,'{"b":999}'); INSERT INTO result SELECT id,x->'a',CASE WHEN subtype(x->'a') THEN 'json' ELSE typeof(x->'a') END,x->>'a',CASE WHEN subtype(x->>'a') THEN 'json' ELSE typeof(x->>'a') END,json_extract(x,'$.a'),CASE WHEN subtype(json_extract(x,'$.a')) THEN 'json' ELSE typeof(json_extract(x,'$.a')) END FROM t1 ORDER BY id;